const d = $input.first().json;

// ============================================================
// HELPERS
// ============================================================

function hasValue(val) {
  return val && String(val).trim() !== '';
}

function historyLine(label, value) {
  if (!hasValue(value)) return '';
  return `${label}: ${value}\n`;
}

function callOutcomeLine(callNumber, timestamp, outcome) {
  if (!hasValue(timestamp)) return '';
  let descriptor;
  if (outcome === 'human_conversation') {
    descriptor = 'connected with supplier (see reply below)';
  } else if (outcome === 'voicemail') {
    descriptor = 'went to voicemail';
  } else if (outcome === 'failed') {
    descriptor = 'call did not connect';
  } else {
    descriptor = 'call attempted';
  }
  return `Reminder call ${callNumber}: made ${timestamp} — ${descriptor}\n`;
}

// ============================================================
// GROUP CONTEXT
// ============================================================

const lineItems = Array.isArray(d.group_line_items) && d.group_line_items.length > 0
  ? d.group_line_items
  : [{
      po_line_item: d.po_line_item,
      material_code: d.material_code,
      material_name: d.material_name,
      quantity: d.quantity,
      unit_of_measure: d.unit_of_measure,
      deliver_by_date: d.deliver_by_date,
      ship_by_date: d.ship_by_date,
    }];

const isMultiLine = lineItems.length > 1;

// Determine target greeting contact based on colleague routing
const contactName = hasValue(d.supplier_colleague_email) && hasValue(d.supplier_colleague_name)
  ? d.supplier_colleague_name
  : d.supplier_contact_name;

// Resolve stage-specific reply for conditional reminder instruction
const stage = d.follow_up_stage || 'Stage1';
const prefix = stage.toLowerCase().replace('.', '_') + '_';
const hasReply = hasValue(d[prefix + 'supplier_raw_statement']) || (isMultiLine && lineItems.some(li => hasValue(li[prefix + 'supplier_raw_statement'])));
const replyClassification = d[prefix + 'delivery_status_classification'] || '';

let reminderInstruction = '';
if (hasReply) {
  if (replyClassification === 'awaiting_reply') {
    reminderInstruction = `- For reminder emails specifically: the supplier previously replied indicating they would check or get back to us. Acknowledge their previous response in natural language (e.g. "Following up on your last update where you mentioned you would check on this", "wanted to check back in since you mentioned you'd look into this", or similar) and note that the promised check date or update window has now passed. Ask them if they have a confirmed schedule or status update for the purchase order now.`;
  } else if (replyClassification === 'unclear') {
    reminderInstruction = `- For reminder emails specifically: the supplier previously gave a vague response, and we sent a clarification email asking for specific dates, which has gone unanswered. Acknowledge this in natural language (e.g. "Following up on our request for clarification on the delivery schedule", "wanted to check back in regarding the clarification details we requested", or similar). Ask them to confirm if they are on track to meet the delivery dates.`;
  } else {
    reminderInstruction = `- For reminder emails specifically: the supplier previously responded. Acknowledge their response in natural language and ask them to confirm if the delivery remains on track for the required dates.`;
  }
} else {
  reminderInstruction = `- For reminder emails specifically: do not make assumptions about why the supplier has not responded. Do not include any phrases that speculate about their busyness, timing, or reasons for not replying. Simply acknowledge that you have not heard back and move to the ask.`;
}


// ============================================================
// PER-STAGE REPLY RENDERER (per-line for multi-line POs)
// ============================================================

function renderStageReply(stagePrefix, eventLabel = 'Supplier reply received') {
  if (!isMultiLine) {
    const raw = d[stagePrefix + '_supplier_raw_statement'];
    if (!hasValue(raw)) return '';
    let out = `\n${eventLabel} (${d[stagePrefix + '_reply_timestamp']}):\n`;
    out += historyLine('Classification', d[stagePrefix + '_delivery_status_classification']);
    out += historyLine('Detail', d[stagePrefix + '_delivery_status_text']);
    out += `What supplier said: ${raw}\n\n`;
    return out;
  }

  const anyReply = lineItems.some(li => hasValue(li[stagePrefix + '_supplier_raw_statement']));
  if (!anyReply) return '';

  let out = `\n${eventLabel} — per line item:\n`;
  for (const li of lineItems) {
    const raw = li[stagePrefix + '_supplier_raw_statement'];
    if (!hasValue(raw)) continue;
    out += `\nLine item ${li.po_line_item} (${li.material_name}):\n`;
    out += historyLine('  Classification', li[stagePrefix + '_delivery_status_classification']);
    out += historyLine('  Detail', li[stagePrefix + '_delivery_status_text']);
    out += historyLine('  Reply timestamp', li[stagePrefix + '_reply_timestamp']);
    out += `  What supplier said: ${raw}\n`;
  }
  out += '\n';
  return out;
}

// ============================================================
// PRIOR COMMUNICATION HISTORY BUILDER
// ============================================================

let historyBlock = '';

// --- STAGE 1 HISTORY ---
const s1HasAnything = hasValue(d.stage1_outreach_body) ||
  hasValue(d.stage1_reminder_mail1_body) ||
  hasValue(d.stage1_reminder_mail2_body) ||
  hasValue(d.stage1_reminder_mail3_body) ||
  hasValue(d.stage1_reminder_call1_timestamp) ||
  hasValue(d.stage1_reminder_call2_timestamp) ||
  hasValue(d.stage1_reminder_call3_timestamp) ||
  hasValue(d.stage1_supplier_raw_statement) ||
  (isMultiLine && lineItems.some(li => hasValue(li.stage1_supplier_raw_statement)));

if (s1HasAnything) {
  historyBlock += `\n=== STAGE 1 COMMUNICATION HISTORY ===\n`;
  historyBlock += `Purpose of Stage 1: First outreach after PO issuance — confirm receipt and delivery on track.\n\n`;

  if (hasValue(d.stage1_outreach_body)) {
    historyBlock += `Outreach email (sent ${d.stage1_outreach_timestamp}):\n${d.stage1_outreach_body}\n\n`;
  }
  if (hasValue(d.stage1_reminder_mail1_body)) {
    historyBlock += `Reminder email 1 (sent ${d.stage1_reminder_mail1_timestamp}):\n${d.stage1_reminder_mail1_body}\n\n`;
  } else if (hasValue(d.stage1_outreach_body) && hasValue(d.stage1_supplier_raw_statement)) {
    historyBlock += `Reminder email 1: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage1_reminder_mail2_body)) {
    historyBlock += `Reminder email 2 (sent ${d.stage1_reminder_mail2_timestamp}):\n${d.stage1_reminder_mail2_body}\n\n`;
  } else if (hasValue(d.stage1_reminder_mail1_body) && hasValue(d.stage1_supplier_raw_statement)) {
    historyBlock += `Reminder email 2: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage1_reminder_mail3_body)) {
    historyBlock += `Reminder email 3 (sent ${d.stage1_reminder_mail3_timestamp}):\n${d.stage1_reminder_mail3_body}\n\n`;
  } else if (hasValue(d.stage1_reminder_mail2_body) && hasValue(d.stage1_supplier_raw_statement)) {
    historyBlock += `Reminder email 3: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage1_reminder_call1_timestamp)) {
    historyBlock += callOutcomeLine(1, d.stage1_reminder_call1_timestamp, d.stage1_reminder_call1_call_outcome);
  } else if (hasValue(d.stage1_reminder_mail3_body) && hasValue(d.stage1_supplier_raw_statement)) {
    historyBlock += `Reminder call 1: not made — supplier replied before this was due.\n`;
  }
  if (hasValue(d.stage1_reminder_call2_timestamp)) {
    historyBlock += callOutcomeLine(2, d.stage1_reminder_call2_timestamp, d.stage1_reminder_call2_call_outcome);
  } else if (hasValue(d.stage1_reminder_call1_timestamp) && hasValue(d.stage1_supplier_raw_statement)) {
    historyBlock += `Reminder call 2: not made — supplier replied before this was due.\n`;
  }
  if (hasValue(d.stage1_reminder_call3_timestamp)) {
    historyBlock += callOutcomeLine(3, d.stage1_reminder_call3_timestamp, d.stage1_reminder_call3_call_outcome);
  } else if (hasValue(d.stage1_reminder_call2_timestamp) && hasValue(d.stage1_supplier_raw_statement)) {
    historyBlock += `Reminder call 3: not made — supplier replied before this was due.\n`;
  }

  historyBlock += renderStageReply('stage1');

  // Inject Clarification History if sent during Stage 1
  const s1Ack = d.stage1_acknowledgment_sent || '';
  if (s1Ack.startsWith('Clarification')) {
    historyBlock += `Clarification email sent (sent ${d.stage1_clarification_sent_timestamp}): [System sent an email asking the supplier to clarify their unclear reply and provide specific delivery dates]\n\n`;
  }
}

// --- STAGE 1.5 MONITORING REPLY ---
const s15HasReply = hasValue(d.stage1_5_supplier_raw_statement) ||
  (isMultiLine && lineItems.some(li => hasValue(li.stage1_5_supplier_raw_statement)));
if (s15HasReply) {
  historyBlock += `=== STAGE 1.5 MONITORING PERIOD ===\n`;
  historyBlock += `Purpose: Passive monitoring gap between Stage 1 and Stage 2. No outbound actions taken — supplier communication received during this period.\n`;
  historyBlock += renderStageReply('stage1_5', 'Supplier update received');
}

// --- STAGE 2 HISTORY ---
const s2HasAnything = hasValue(d.stage2_outreach_body) ||
  hasValue(d.stage2_reminder_mail1_body) ||
  hasValue(d.stage2_reminder_mail2_body) ||
  hasValue(d.stage2_reminder_mail3_body) ||
  hasValue(d.stage2_reminder_call1_timestamp) ||
  hasValue(d.stage2_reminder_call2_timestamp) ||
  hasValue(d.stage2_reminder_call3_timestamp) ||
  hasValue(d.stage2_supplier_raw_statement) ||
  (isMultiLine && lineItems.some(li => hasValue(li.stage2_supplier_raw_statement)));

if (s2HasAnything) {
  historyBlock += `\n=== STAGE 2 COMMUNICATION HISTORY ===\n`;
  historyBlock += `Purpose of Stage 2: Pre-delivery check-in — confirm order is on track to be delivered by the deliver-by date(s) for this PO.\n\n`;

  if (hasValue(d.stage2_outreach_body)) {
    historyBlock += `Outreach email (sent ${d.stage2_outreach_timestamp}):\n${d.stage2_outreach_body}\n\n`;
  }
  if (hasValue(d.stage2_reminder_mail1_body)) {
    historyBlock += `Reminder email 1 (sent ${d.stage2_reminder_mail1_timestamp}):\n${d.stage2_reminder_mail1_body}\n\n`;
  } else if (hasValue(d.stage2_outreach_body) && hasValue(d.stage2_supplier_raw_statement)) {
    historyBlock += `Reminder email 1: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage2_reminder_mail2_body)) {
    historyBlock += `Reminder email 2 (sent ${d.stage2_reminder_mail2_timestamp}):\n${d.stage2_reminder_mail2_body}\n\n`;
  } else if (hasValue(d.stage2_reminder_mail1_body) && hasValue(d.stage2_supplier_raw_statement)) {
    historyBlock += `Reminder email 2: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage2_reminder_mail3_body)) {
    historyBlock += `Reminder email 3 (sent ${d.stage2_reminder_mail3_timestamp}):\n${d.stage2_reminder_mail3_body}\n\n`;
  } else if (hasValue(d.stage2_reminder_mail2_body) && hasValue(d.stage2_supplier_raw_statement)) {
    historyBlock += `Reminder email 3: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage2_reminder_call1_timestamp)) {
    historyBlock += callOutcomeLine(1, d.stage2_reminder_call1_timestamp, d.stage2_reminder_call1_call_outcome);
  } else if (hasValue(d.stage2_reminder_mail3_body) && hasValue(d.stage2_supplier_raw_statement)) {
    historyBlock += `Reminder call 1: not made — supplier replied before this was due.\n`;
  }
  if (hasValue(d.stage2_reminder_call2_timestamp)) {
    historyBlock += callOutcomeLine(2, d.stage2_reminder_call2_timestamp, d.stage2_reminder_call2_call_outcome);
  } else if (hasValue(d.stage2_reminder_call1_timestamp) && hasValue(d.stage2_supplier_raw_statement)) {
    historyBlock += `Reminder call 2: not made — supplier replied before this was due.\n`;
  }
  if (hasValue(d.stage2_reminder_call3_timestamp)) {
    historyBlock += callOutcomeLine(3, d.stage2_reminder_call3_timestamp, d.stage2_reminder_call3_call_outcome);
  } else if (hasValue(d.stage2_reminder_call2_timestamp) && hasValue(d.stage2_supplier_raw_statement)) {
    historyBlock += `Reminder call 3: not made — supplier replied before this was due.\n`;
  }

  historyBlock += renderStageReply('stage2');

  // Inject Clarification History if sent during Stage 2
  const s2Ack = d.stage2_acknowledgment_sent || '';
  if (s2Ack.startsWith('Clarification')) {
    historyBlock += `Clarification email sent (sent ${d.stage2_clarification_sent_timestamp}): [System sent an email asking the supplier to clarify their unclear reply and provide specific delivery dates]\n\n`;
  }
}

// --- STAGE 2.5 MONITORING REPLY ---
const s25HasReply = hasValue(d.stage2_5_supplier_raw_statement) ||
  (isMultiLine && lineItems.some(li => hasValue(li.stage2_5_supplier_raw_statement)));
if (s25HasReply) {
  historyBlock += `=== STAGE 2.5 MONITORING PERIOD ===\n`;
  historyBlock += `Purpose: Passive monitoring gap between Stage 2 and Stage 3. No outbound actions taken — supplier communication received during this period.\n`;
  historyBlock += renderStageReply('stage2_5');
}

// --- STAGE 3 HISTORY ---
const s3HasAnything = hasValue(d.stage3_outreach_body) ||
  hasValue(d.stage3_reminder_mail1_body) ||
  hasValue(d.stage3_reminder_mail2_body) ||
  hasValue(d.stage3_reminder_mail3_body) ||
  hasValue(d.stage3_reminder_call1_timestamp) ||
  hasValue(d.stage3_reminder_call2_timestamp) ||
  hasValue(d.stage3_reminder_call3_timestamp) ||
  hasValue(d.stage3_supplier_raw_statement) ||
  (isMultiLine && lineItems.some(li => hasValue(li.stage3_supplier_raw_statement)));

if (s3HasAnything) {
  historyBlock += `\n=== STAGE 3 COMMUNICATION HISTORY ===\n`;
  historyBlock += `Purpose of Stage 3: Shipment status verification — confirm goods have been or are about to be dispatched ahead of the ship-by date(s) for this PO.\n\n`;

  if (hasValue(d.stage3_outreach_body)) {
    historyBlock += `Outreach email (sent ${d.stage3_outreach_timestamp}):\n${d.stage3_outreach_body}\n\n`;
  }
  if (hasValue(d.stage3_reminder_mail1_body)) {
    historyBlock += `Reminder email 1 (sent ${d.stage3_reminder_mail1_timestamp}):\n${d.stage3_reminder_mail1_body}\n\n`;
  } else if (hasValue(d.stage3_outreach_body) && hasValue(d.stage3_supplier_raw_statement)) {
    historyBlock += `Reminder email 1: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage3_reminder_mail2_body)) {
    historyBlock += `Reminder email 2 (sent ${d.stage3_reminder_mail2_timestamp}):\n${d.stage3_reminder_mail2_body}\n\n`;
  } else if (hasValue(d.stage3_reminder_mail1_body) && hasValue(d.stage3_supplier_raw_statement)) {
    historyBlock += `Reminder email 2: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage3_reminder_mail3_body)) {
    historyBlock += `Reminder email 3 (sent ${d.stage3_reminder_mail3_timestamp}):\n${d.stage3_reminder_mail3_body}\n\n`;
  } else if (hasValue(d.stage3_reminder_mail2_body) && hasValue(d.stage3_supplier_raw_statement)) {
    historyBlock += `Reminder email 3: not sent — supplier replied before this was due.\n\n`;
  }
  if (hasValue(d.stage3_reminder_call1_timestamp)) {
    historyBlock += callOutcomeLine(1, d.stage3_reminder_call1_timestamp, d.stage3_reminder_call1_call_outcome);
  } else if (hasValue(d.stage3_reminder_mail3_body) && hasValue(d.stage3_supplier_raw_statement)) {
    historyBlock += `Reminder call 1: not made — supplier replied before this was due.\n`;
  }
  if (hasValue(d.stage3_reminder_call2_timestamp)) {
    historyBlock += callOutcomeLine(2, d.stage3_reminder_call2_timestamp, d.stage3_reminder_call2_call_outcome);
  } else if (hasValue(d.stage3_reminder_call1_timestamp) && hasValue(d.stage3_supplier_raw_statement)) {
    historyBlock += `Reminder call 2: not made — supplier replied before this was due.\n`;
  }
  if (hasValue(d.stage3_reminder_call3_timestamp)) {
    historyBlock += callOutcomeLine(3, d.stage3_reminder_call3_timestamp, d.stage3_reminder_call3_call_outcome);
  } else if (hasValue(d.stage3_reminder_call2_timestamp) && hasValue(d.stage3_supplier_raw_statement)) {
    historyBlock += `Reminder call 3: not made — supplier replied before this was due.\n`;
  }

  historyBlock += renderStageReply('stage3');

  // Inject Clarification History if sent during Stage 3
  const s3Ack = d.stage3_acknowledgment_sent || '';
  if (s3Ack.startsWith('Clarification')) {
    historyBlock += `Clarification email sent (sent ${d.stage3_clarification_sent_timestamp}): [System sent an email asking the supplier to clarify their unclear reply and provide specific delivery dates]\n\n`;
  }
}

// ============================================================
// STAGE DEFINITIONS
// ============================================================

const daysToShipBy = Math.round(
  (new Date(d.ship_by_date) - new Date()) / (1000 * 60 * 60 * 24)
);
const shipByContext = daysToShipBy > 0
  ? `${daysToShipBy} day(s) from today`
  : daysToShipBy === 0
  ? 'today'
  : `${Math.abs(daysToShipBy)} day(s) ago`;

const stageDefinitions = `
=== STAGE DEFINITIONS ===

Stage 1 — First outreach after PO issuance.
Purpose: Confirm the supplier has received the purchase order and will be able to deliver by the required delivery date(s) for this PO.

Stage 1.5 — Monitoring period between Stage 1 and Stage 2.
Purpose: Passive period where no outbound action is taken. Stage 1 has confirmed the order is on track or escalated to the buyer if not. The system simply waits and listens for any proactive communications from supplier until Stage 2 begins. The only outbound action is an acknowledgment email if communication is received from the supplier.

Stage 2 — Pre-delivery check-in.
Purpose: As the delivery date approaches, confirm the order is still on track to be delivered by the required delivery date(s) for this PO.

Stage 2.5 — Monitoring period between Stage 2 and Stage 3.
Purpose: Passive period where no outbound action is taken. Stage 2 has confirmed the order is still on track approaching the ship-by date or escalated to the buyer if not. The system waits for any proactive communications from supplier until Stage 3 begins. The only outbound action is an acknowledgment email if communication is received from the supplier.

Stage 3 — Shipment status verification.
Purpose: The delivery date is imminent. Confirm whether the goods have been or are about to be dispatched ahead of the ship-by date(s) for this PO. The ship-by date is the date by which goods must leave the supplier's facility to arrive by the required delivery date.
`;

// ============================================================
// PO DETAILS SECTION (dual rendering)
// ============================================================

let poDetailsBlock;
if (isMultiLine) {
  const lineItemBlocks = lineItems.map(li => {
    const qtyDisplay = hasValue(li.quantity)
      ? `${li.quantity} ${li.unit_of_measure || ''}`.trim()
      : 'Not specified';
    const matLine = hasValue(li.material_code)
      ? `- Material: ${li.material_name} (Material Code: ${li.material_code})`
      : `- Material: ${li.material_name}`;
    return `Line item ${li.po_line_item}:
${matLine}
- Quantity: ${qtyDisplay}
- Expected Delivery Date: ${li.deliver_by_date}
- Ship By Date: ${li.ship_by_date}`;
  }).join('\n\n');

  poDetailsBlock = `PO Number: ${d.po_number}
Supplier Company: ${d.supplier_name}
Supplier Contact: ${contactName}
PO Issue Date: ${d.issue_date}

This PO contains ${lineItems.length} line items:

${lineItemBlocks}

Sender Name: ${d.ai_agent_buyer_name}
Sender Position: ${d.ai_agent_buyer_position}
On behalf of: ${d.client_buyer_name}, ${d.client_buyer_position} at ${d.client_company_name}`;
} else {
  poDetailsBlock = `PO Number: ${d.po_number}
Material: ${d.material_name}${hasValue(d.material_code) ? ` (Material Code: ${d.material_code})` : ''}
Quantity: ${hasValue(d.quantity) ? `${d.quantity} ${d.unit_of_measure}` : 'Not specified'}
Supplier Company: ${d.supplier_name}
Supplier Contact: ${contactName}
PO Issue Date: ${d.issue_date}
Expected Delivery Date: ${d.deliver_by_date}
Ship By Date: ${d.ship_by_date}
Sender Name: ${d.ai_agent_buyer_name}
Sender Position: ${d.ai_agent_buyer_position}
On behalf of: ${d.client_buyer_name}, ${d.client_buyer_position} at ${d.client_company_name}`;
}

// ============================================================
// BOLDING RULES (dual)
// ============================================================

const boldingRulesBlock = isMultiLine
  ? `4. Bolding: Use HTML <b>...</b> tags to bold the following pieces of information in the email body:
   - The PO# (the full string "PO# ${d.po_number}")
   Do NOT bold material names, dates, or anything else in the prose. The pre-built table (inserted via placeholder, see below) handles visual emphasis for line item details.
   Use <b> tags only. Do not use markdown asterisks. Do not use any other formatting tags.`
  : `4. Bolding: Use HTML <b>...</b> tags to bold the following pieces of information wherever they appear in the email body:
   - The PO# (the full string "PO# ${d.po_number}")
   - The material name
   - The material code (if mentioned)
   - The required delivery date (${d.deliver_by_date}) when referenced as the delivery commitment
   - The ship-by date (${d.ship_by_date}) when referenced as the dispatch commitment

Bold only the date itself, not the surrounding phrase. For example: "delivery by <b>May 21</b>", not "<b>delivery by May 21</b>".

Do NOT bold other dates such as the PO issue date, prior email or call timestamps, or supplier-stated revised dates.

Use <b> tags only. Do not use markdown asterisks. Do not use any other formatting tags.`;

// ============================================================
// TABLE INSTRUCTION (multi-line only)
// ============================================================

const tableInstructionBlock = isMultiLine ? `

--- HOW TO REFERENCE LINE ITEMS IN THE EMAIL BODY ---

This PO has multiple line items. A pre-built HTML table containing all line items will be inserted into the email body.

In your email_body output, write the placeholder {{TABLE_PLACEHOLDER}} on its own line where the line item details should appear. Do NOT write out the table yourself. The system will replace this placeholder with the pre-built table.

Example structure:
"Hi [contact],
I'm writing about PO# [number]. Please confirm receipt and ability to meet the delivery dates for the items below:

{{TABLE_PLACEHOLDER}}

Could you confirm [...]?"

Do not reference specific line items by name in the prose (e.g. don't write "the Mild Steel Brackets and Carbon steel tubes" or "Line 10 and Line 30"). Refer to the line items collectively using phrases like "the items below", "the line items in this PO", or similar.` : '';

// ============================================================
// PRE-BUILT HTML TABLE (multi-line only)
// ============================================================

function formatDateShort(isoDate) {
  if (!hasValue(isoDate)) return '';
  const dt = new Date(isoDate);
  if (isNaN(dt.getTime())) return isoDate;
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const monthStr = months[dt.getMonth()];
  const dayStr = dt.getDate();
  const currentYear = new Date().getFullYear();
  return dt.getFullYear() === currentYear
    ? `${monthStr} ${dayStr}`
    : `${monthStr} ${dayStr}, ${dt.getFullYear()}`;
}

let poDetailsTableHtml = '';
if (isMultiLine) {
  const cellStyle = 'border: 1px solid #ccc; padding: 8px 12px; text-align: left; font-family: Arial, sans-serif; font-size: 14px;';
  const headerCellStyle = cellStyle + ' background-color: #f5f5f5; font-weight: bold;';

  const rows = lineItems.map((li, idx) => {
    const qty = hasValue(li.quantity)
      ? `${li.quantity} ${li.unit_of_measure || ''}`.trim()
      : '';
    return `<tr><td style="${cellStyle}">${idx + 1}</td><td style="${cellStyle}">${li.material_code || ''}</td><td style="${cellStyle}">${li.material_name || ''}</td><td style="${cellStyle}">${qty}</td><td style="${cellStyle}">${formatDateShort(li.deliver_by_date)}</td></tr>`;
  }).join('');

  poDetailsTableHtml = `<table style="border-collapse: collapse; font-family: Arial, sans-serif; font-size: 14px;"><thead><tr><th style="${headerCellStyle}">#</th><th style="${headerCellStyle}">Material Code</th><th style="${headerCellStyle}">Material Name</th><th style="${headerCellStyle}">Quantity</th><th style="${headerCellStyle}">Required Delivery Date</th></tr></thead><tbody>${rows}</tbody></table>`;
}

// ============================================================
