let to = primaryContact;
let ccList = [];

const targetRecipient = (actualReplier && actualReplier.trim() !== '') ? actualReplier : colleagueEmail;

if (targetRecipient && targetRecipient.toLowerCase() !== primaryContact.toLowerCase()) {
  to = targetRecipient;
  ccList.push(primaryContact);
}

if (ctx.client_buyer_email) {
  ccList.push(ctx.client_buyer_email);
}

const cc = ccList.join(', ');
const from = ctx.ai_agent_buyer_email;

// CRITICAL FIX: Extract generated text from Claude's dynamic response format
const bodyText = d.email_body || d.acknowledgment_body || d.body || (d.content && d.content[0] && d.content[0].text) || d.text || '';
const body = bodyText
     .replace(/>\s*\n\s*</g, '><')
     .replace(/\n/g, '<br>');

// 3. Threading headers setup
const threadId = 
  rawLogs[`${prefix}supplier_reply_thread_id`] ||
  ctx[`${prefix}supplier_reply_thread_id`] ||
  ctx.supplier_reply_thread_id ||
  rawLogs[`${prefix}outreach_thread_id`] ||
  ctx[`${prefix}outreach_thread_id`] ||
  ctx.outreach_thread_id ||
  '';

const originalMessageId = 
  rawLogs[`${prefix}supplier_reply_message_id`] ||
  ctx[`${prefix}supplier_reply_message_id`] ||
  ctx.supplier_reply_message_id ||
  rawLogs[`${prefix}outreach_message_id`] ||
  ctx[`${prefix}outreach_message_id`] ||
  ctx.outreach_message_id ||
  '';

const headers = [
  `From: ${from}`,
  `To: ${to}`,
  ...(cc ? [`Cc: ${cc}`] : []),
  `Subject: ${subject}`,
  `MIME-Version: 1.0`,
  `Content-Type: text/html; charset=utf-8`,
];

let formattedMessageId = (originalMessageId || '').trim();
if (formattedMessageId && formattedMessageId.includes('@')) {
  if (!formattedMessageId.startsWith('<')) formattedMessageId = '<' + formattedMessageId;
  if (!formattedMessageId.endsWith('>')) formattedMessageId = formattedMessageId + '>';

  headers.push(`In-Reply-To: ${formattedMessageId}`);
  headers.push(`References: ${formattedMessageId}`);
}

const emailLines = [...headers, ``, body].join('\r\n');
const raw = Buffer.from(emailLines, 'utf8')
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=/g, '');

const baseBody = { raw: raw };
if (threadId) baseBody.threadId = threadId;
const requestBody = JSON.stringify(baseBody);

return [{
  json: {
    ...d,
    email_raw: raw,
    request_body: requestBody,
    email_subject: subject,
    email_body: bodyText, // Output for Approval Gate preview
    email_send_mode_direct_or_draft: ctx.email_send_mode_direct_or_draft, // Output for 'Check - Send Mode'
  }
}];

const d = $input.first().json;
const action = d.action; // 'send_clarification1' or 'send_clarification2'
const stage = d.follow_up_stage || 'Stage1';
const prefix = stage.toLowerCase().replace('.', '_') + '_';

const ackValue = action === 'send_clarification1' ? 'Clarification_1' : 'Clarification_2';
const now = new Date().toISOString();

return [{
  json: {
    po_line_key: d.po_line_key,
    follow_up_status: 'Clarification_Sent',
    last_action_timestamp: now,
    [`${prefix}acknowledgment_sent`]: ackValue,
    [`${prefix}supplier_reply_status`]: 'Clarification Sent',
    [`${prefix}clarification_sent_timestamp`]: now
  }
}];
